import { chromium } from 'playwright';
const browser=await chromium.launch({channel:'chrome',headless:true,args:['--use-fake-ui-for-media-stream','--use-fake-device-for-media-stream','--autoplay-policy=no-user-gesture-required']});
const base='http://127.0.0.1:4173/calculator/';
const fakeSupabase=`(()=>{class Ch{constructor(topic){this.handlers=[];this.bc=new BroadcastChannel('sb-'+topic);this.bc.onmessage=e=>{const m=e.data||{};this.handlers.filter(h=>h.event===m.event).forEach(h=>h.cb({payload:m.payload}))}}on(type,filter,cb){if(type==='broadcast')this.handlers.push({event:filter.event,cb});return this}subscribe(cb){setTimeout(()=>cb&&cb('SUBSCRIBED'),0);return this}async httpSend(event,payload){this.bc.postMessage({event,payload});return {status:'ok'}}close(){this.bc.close()}}window.supabase={createClient(){return{channel(topic){return new Ch(topic)},async removeChannel(ch){ch?.close?.();return true}}}}})();`;
const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,permissions:['microphone','camera']});await context.route('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2*',r=>r.fulfill({status:200,contentType:'application/javascript',body:fakeSupabase}));
async function makePhone(number){const page=await context.newPage();await page.addInitScript(n=>{const g=Storage.prototype.getItem,s=Storage.prototype.setItem;let own=n;Storage.prototype.getItem=function(k){if(k==='calculator-number')return own;return g.call(this,k)};Storage.prototype.setItem=function(k,v){if(k==='calculator-number'){own=String(v);return}return s.call(this,k,v)};localStorage.setItem('main-code','5963')},number);const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await page.goto(base,{waitUntil:'load',timeout:20000});for(const d of ['5','9','6','3'])await page.locator(`#calc [data-v="${d}"]`).click();await page.locator('#calc [data-a="eq"]').click();await page.locator('.calculator-phone-launch').first().waitFor({state:'visible',timeout:7000});return{page,errors}}
const A=await makePhone('111-111-1111'),B=await makePhone('222-222-2222');
await A.page.locator('.calculator-phone-launch').first().click({timeout:3000});await A.page.locator('#app.screen.active .phone-app-page').waitFor({state:'visible',timeout:3000});const keys=await A.page.locator('.dialpad .dial-key').allTextContents();console.log('DIAL_KEYS',JSON.stringify(keys));if(keys.length<10)throw new Error('Dialpad did not render');const two=A.page.locator('.dialpad .dial-key').nth(1);for(let i=0;i<10;i++)await two.evaluate(el=>el.click());const dial=(await A.page.locator('.dial-number').textContent())?.trim();if(dial!=='222-222-2222')throw new Error('Caller dialpad produced '+dial);
await A.page.locator('.dial-call').evaluate(el=>el.click());await B.page.locator('#calcCallOverlay #accept').waitFor({state:'visible',timeout:5000});const incomingText=(await B.page.locator('#calcCallOverlay').textContent())||'';console.log('INCOMING_OVERLAY',incomingText.replace(/\s+/g,' ').trim());if(!incomingText.includes('111-111-1111'))throw new Error('Incoming call did not show caller number');const ringResponsive=await B.page.evaluate(()=>new Promise(r=>setTimeout(()=>r(true),700)));if(!ringResponsive)throw new Error('Incoming ringtone blocked UI');await B.page.locator('#calcCallOverlay #accept').click({timeout:3000});
await A.page.waitForFunction(()=>document.querySelector('#callStatus')?.textContent==='Connected',{timeout:15000}).catch(()=>{});const aStatus=(await A.page.locator('#callStatus').textContent().catch(()=>''))||'';const bOverlay=await B.page.locator('#calcCallOverlay').count();console.log('CALLER_STATUS',aStatus,'CALLEE_OVERLAY',bOverlay);if(!bOverlay)throw new Error('Callee call screen disappeared after answer');const endB=B.page.locator('#calcCallOverlay #callEnd').first();if(await endB.count())await endB.evaluate(el=>el.click());else{const endA=A.page.locator('#calcCallOverlay #callEnd').first();if(await endA.count())await endA.evaluate(el=>el.click());else throw new Error('No hangup button after answer')}
await A.page.waitForFunction(()=>!document.getElementById('calcCallOverlay'),{timeout:5000});await B.page.waitForFunction(()=>!document.getElementById('calcCallOverlay'),{timeout:5000});if(A.errors.length||B.errors.length)throw new Error('Browser errors: '+[...A.errors,...B.errors].join(' | '));console.log('CALCULATOR_TWO_PHONE_CALL_TEST_PASS');await context.close();await browser.close();